<?php require 'bootstrap.php';admin_header('ภาพรวมร้านค้า');$pendingSlips=(int)q('SELECT COUNT(*) FROM orders WHERE payment_status="pending_review"')->fetchColumn();echo '<div class="notice"><a href="'.url('admin/orders.php?payment=pending_review').'">สลิปรอตรวจสอบ '.$pendingSlips.' รายการ</a></div>';$stats=['สินค้าที่ใช้งาน'=>'SELECT COUNT(*) FROM products WHERE active=1','สมาชิก'=>'SELECT COUNT(*) FROM users WHERE role="customer"','คำสั่งซื้อ'=>'SELECT COUNT(*) FROM orders','ยอดขายส่งสำเร็จ'=>'SELECT COALESCE(SUM(total),0) FROM orders WHERE status="delivered"'];?><div class="stats"><?php foreach($stats as $label=>$sql):?><div class="panel"><small><?=e(t($label))?></small><h2><?=$label==='ยอดขายส่งสำเร็จ'?money(q($sql)->fetchColumn()):q($sql)->fetchColumn()?></h2></div><?php endforeach ?></div><p>ยอดขายรวมค่าจัดส่ง เฉพาะคำสั่งซื้อที่จัดส่งสำเร็จ แยกจากสถานะรับเงิน</p><h2>คำสั่งซื้อล่าสุด</h2><?php foreach(q('SELECT id,total,status FROM orders ORDER BY id DESC LIMIT 8') as $o):?><p><a href="order_detail.php?id=<?=$o['id']?>">BP-<?=$o['id']?></a> · <?=money($o['total'])?> · <?=STATUSES[$o['status']]?></p><?php endforeach ?><h2>สรุปสถานะ</h2><?php foreach(q('SELECT status,COUNT(*) n FROM orders GROUP BY status') as $r):?><p><?=STATUSES[$r['status']]?>: <?=$r['n']?></p><?php endforeach ?><h2>สินค้าใกล้หมด (ไม่เกิน 5 ชิ้น)</h2><?php foreach(q('SELECT name,stock FROM products WHERE active=1 AND stock<=low_stock_threshold ORDER BY stock') as $p):?><p><?=e(localized_name($p))?> · <?=$p['stock']?> <?=e(t('ชิ้น'))?></p><?php endforeach;admin_footer();?>
